mapper.select:
SELECT COUNT(*)
  FROM CHATBOT_LINK_CLICK
 WHERE clicked_at >= #{from}
   AND clicked_at <  #{to}

SELECT url            AS url,
       COUNT(*)       AS clickCount
  FROM CHATBOT_LINK_CLICK
 WHERE clicked_at >= #{from}
   AND clicked_at <  #{to}
 GROUP BY url
 ORDER BY clickCount DESC, url ASC
 LIMIT #{limit}
